window.LD=window.LD||{};window.LD["party/p3"]={"id":"p3","name":"The Amber Sigil","poss":"The Amber Sigil's","members":["h11","h2","h16"],"leader":"h2","morale":80,"disposition":"predatory","motto":"Dirty tricks, clean results.","banner":{"c1":"#2f9e9e","c2":"#e8823a","emblem":"eye"},"loc":"veldrock","loc_name":"Veldrock","goal":{"text":"to earn 3,100 silver between them before the season ends","kind":"purse","done":null,"progress":"1,144 of 3,100 silver","missed":true,"crew":"The Amber Sigil","party":"p3"},"vows":[{"text":"never to retreat","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Amber Sigil","party":"p3"}],"doing":"last seen delving into Emberdeep","progress":null,"today":["XP: Quill +50, Sela +38.","Coin between them: -139 silver (tables 91, beds 31, tavern 9)."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":148,"season":{"wins":6,"bosses":0,"floors":5,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":4},"career":{"wins":27,"bosses":1,"floors":15,"gold":0,"deaths":0,"fled":1,"pvp_wins":2,"pvp_losses":2,"renown":0,"days":90,"arguments":7},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"covered_wagon","name":"Lady Luck","label":"covered wagon","seats":4,"haul":45,"comfort":-1,"since":89,"desc":"A roof, a lantern, and somewhere dry to sleep.","moves":true,"puller":{"kind":"horse","name":"Sir Hoofington","label":"riding horse","colour":"buckskin","owner":null},"paid":[["Tamsin",78],["Sela",27],["Quill",15]]},"pace_gap":0,"rels":[{"party":"p1","score":-100},{"party":"p6","score":-100},{"party":"p8","score":-99},{"party":"p4","score":44},{"party":"p5","score":6},{"party":"p2","score":4}],"events":[{"id":"e28","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Quill and Sela shake on it at The Gilded Flagon: they are now The Amber Sigil. (Predatory, by the look of them.)","heroes":["h11","h2"],"parties":["p3"],"loc":"ironhaven","wx":"storm"},{"id":"e491","day":13,"season":1,"sday":13,"kind":"pvp","imp":5,"text":"Red Hammers rout The Amber Sigil on the road between Ashfen and the Ashveil Crypts and walk off with 38 silver. The Amber Sigil comes for a toll and gets a fight instead.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashfen","fight":"f42","losers":["h11","h2","h16"]},{"id":"e653","day":17,"season":1,"sday":17,"kind":"robbery","imp":5,"text":"The Amber Sigil corners Verdant Edge in Bleakmarsh and demands a toll. Verdant Edge pays 27 silver rather than fight. Tamsin (Riley's hero) does the talking. It will not be forgotten.","heroes":["h11","h2","h16","h12","h17"],"parties":["p3","p8"],"loc":"bleakmarsh","wx":"rain"},{"id":"e764","day":20,"season":1,"sday":20,"kind":"road","imp":2,"text":"Jory Bellwether falls in beside Quill for the first time and offers to announce him wherever the road goes. Free of charge, he adds, humbly.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"carrbridge~ironhaven","traveller":"jory","road_rec":"r188"},{"id":"e801","day":21,"season":1,"sday":21,"kind":"boss_race","imp":2,"text":"The Amber Sigil has not given up on Vessimir the Unburied after all: back on the road to the Ashveil Crypts.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e809","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Sela presents a letter of introduction in Carrbridge from a duke who has never heard of him. It works.","heroes":["h2"],"parties":["p3"],"loc":"carrbridge","skill":"forgery"},{"id":"e814","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"A fortnight in The Amber Sigil, and Quill now saves Tamsin the dry side of the tent without being asked.","heroes":["h11","h16"],"parties":["p3"],"loc":"carrbridge"},{"id":"e815","day":21,"season":1,"sday":21,"kind":"campfire","imp":3,"text":"Two weeks together in The Amber Sigil. Sela and Tamsin have a signal now for \"let's leave\". They use it a lot.","heroes":["h2","h16"],"parties":["p3"],"loc":"carrbridge"},{"id":"e862","day":22,"season":1,"sday":22,"kind":"campfire","imp":1,"text":"Sela once called Tamsin's singing a crime. Tonight Sela asks for another verse.","heroes":["h2","h16"],"parties":["p3"],"loc":"carrbridge"},{"id":"e916","day":24,"season":1,"sday":24,"kind":"night","imp":3,"text":"Something small and clever gets into The Amber Sigil's camp in the Ashveil Crypts overnight. Tamsin wakes up 10 silver and 2 rations lighter.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e933","day":24,"season":1,"sday":24,"kind":"meet","imp":2,"text":"Nobody offers to share a fire when The Amber Sigil and Red Hammers meet on the road between Ashfen and the Ashveil Crypts. Two small fires burn instead, twenty paces apart.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashfen","wx":"fog"},{"id":"e935","day":24,"season":1,"sday":24,"kind":"tarot","imp":2,"text":"Sela lays three cards on a flat stone for The Amber Sigil, with the Ashveil Crypts a short walk off in the dark: the Moon, the Knight of Swords and the Empress. A mixed spread.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","reading":"r217","wx":"fog"},{"id":"e938","day":24,"season":1,"sday":24,"kind":"campfire","imp":2,"text":"Quill brings back a brace of rabbits for the pot. Tamsin cooks them. Teamwork.","heroes":["h11","h16"],"parties":["p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e952","day":25,"season":1,"sday":25,"kind":"delve","imp":1,"text":"The Amber Sigil descends into the Ashveil Crypts, partly explored (46%), map in hand.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e953","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"By lamplight on the second floor of the Ashveil Crypts, The Amber Sigil clears the way through seven rooms, at a steady pace: the cold room, the chapel of the weeping saint, the chapel of statues and 4 more.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":7,"empty":7,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e958","day":25,"season":1,"sday":25,"kind":"ambush","imp":2,"text":"The Amber Sigil beats 3 Skeletons at their camp on the second floor of the Ashveil Crypts, in the middle of the night. Tamsin put Fire Arrow into the skeleton to end it, and lowered the bow. Quill did more than his share and will mention it. An arrow that should have found Tamsin found the strap next to the coin pocket instead. \"Good. What's it worth?\" says Tamsin. Loot: 13 bones, 2 crypt-caps.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f64","foes":["skeleton","skeleton","skeleton"],"where":"at their camp on the second floor of The Ashveil Crypts, in the middle of the night","won":true,"close":false,"shape":"plain","wx":"fog"},{"id":"e964","day":25,"season":1,"sday":25,"kind":"bond","imp":2,"text":"The Amber Sigil and Red Hammers are rivals now, starting with Quill and Bramble. (5 heroes now hold grudges.)","heroes":["h11","h13","h14","h2","h16"],"parties":["p3","p1"],"bond":"rivals"},{"id":"e965","day":25,"season":1,"sday":25,"kind":"pvp","imp":5,"text":"Red Hammers force a surrender from The Amber Sigil at the mouth of the Ashveil Crypts and walk off with 7 silver. The Amber Sigil comes for a toll and gets a fight instead.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashveil_crypts","fight":"f65","losers":["h11","h2","h16"],"wx":"fog"},{"id":"e972","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Tamsin counts the week's takings by lamplight and makes Sela the official second counter, 'for loyalty'. Underworld Royalty: one of the things Tamsin learned the long way round.","heroes":["h16","h2"],"parties":["p3"],"loc":"ashveil_crypts","skill":"underworld_royalty","wx":"fog"},{"id":"e988","day":26,"season":1,"sday":26,"kind":"fight","imp":1,"text":"With Sela taking the worst of it, the Amber Sigil sees off 2 Skeleton Archers and a Skeleton in the funeral feast hall on the second floor of the Ashveil Crypts. The skeleton had been trouble right up until Sela's Smite. Loot: 11 bones, 4 crypt-caps.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f66","foes":["skeleton_archer","skeleton","skeleton_archer"],"where":"in the funeral feast hall on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-34,"wx":"fog"},{"id":"e989","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"Deeper into the second floor of the Ashveil Crypts: The Amber Sigil sees four rooms today, with a look round every corner (the choir loft, the mourners' stair, a hundred worn steps, the bell chamber and 1 more).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":4,"empty":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common","cosmetic"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1007","day":26,"season":1,"sday":26,"kind":"meet","imp":1,"text":"A scout's whistle, a quick detour: Verdant Edge leaves The Amber Sigil the road outside the Ashveil Crypts. Day 17 of season 1 taught them which camps to avoid.","heroes":["h11","h2","h16","h12","h17"],"parties":["p3","p8"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1008","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Tamsin turns round to hand Quill a cup and Quill is already behind Tamsin, holding a cup. Chalk it up to Never Where You Left Them.","heroes":["h11","h16"],"parties":["p3"],"loc":"ashveil_crypts","skill":"never_where_you_left_them","wx":"fog"},{"id":"e1017","day":26,"season":1,"sday":26,"kind":"goal_done","imp":4,"text":"The Amber Sigil can cross it off: earn 300 silver between them before the season ends. Drinks are on them. XP: Quill +960 (level 12!), Sela +960 (level 12!), Tamsin +960 (level 13!).","heroes":["h11","h2","h16"],"parties":["p3"],"xp":{"h11":960,"h2":960,"h16":960}},{"id":"e1027","day":27,"season":1,"sday":27,"kind":"fight","imp":2,"text":"Win number five in a row: the Amber Sigil cuts down 2 Risen Dead, a Skeleton Archer and a Bone Construct in the skeletons' shift room on the second floor of the Ashveil Crypts. Sela's Smite finished the fight. Nobody cheered for Quill's Never Where You Left Them, but it won the fight. Loot: 16 bones, 5 crypt-caps.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f68","foes":["skeleton_archer","bone_construct","zombie"],"where":"in the skeletons' shift room on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"streak","reworded":-26,"wx":"fog"},{"id":"e1028","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"Down in the Ashveil Crypts, The Amber Sigil maps two rooms of the second floor, carefully (the stitching room, the collapsed gallery).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":2,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1039","day":27,"season":1,"sday":27,"kind":"meet","imp":2,"text":"Red Hammers and The Amber Sigil need the same stream at the mouth of the Ashveil Crypts and take turns at it without a word, each side watching the other's hands.","heroes":["h13","h14","h11","h2","h16"],"parties":["p1","p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1056","day":28,"season":1,"sday":28,"kind":"delve_day","imp":1,"text":"The Amber Sigil spends the day on the second floor of the Ashveil Crypts, without hurrying, and covers three rooms: the collapsed gallery, the drowned niches, the Veyne vault.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e1057","day":28,"season":1,"sday":28,"kind":"night","imp":1,"text":"A carter with a broken wheel on the second floor of the Ashveil Crypts pays for The Amber Sigil's help in gossip: the deep rooms of the Wolf Den are open again.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1075","day":28,"season":1,"sday":28,"kind":"meet","imp":1,"text":"The Amber Sigil and Verdant Edge make camp in the Ashveil Crypts on opposite sides of one clearing. Each side posts a watch, and the two watches stare at each other till dawn.","heroes":["h11","h2","h16","h12","h17"],"parties":["p3","p8"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1076","day":28,"season":1,"sday":28,"kind":"talent","imp":2,"text":"Quill rolls under a swinging blade trap, gets up, and dusts off. 'Was there something?' That's Never Where You Left Them for you.","heroes":["h11"],"parties":["p3"],"loc":"ashveil_crypts","skill":"never_where_you_left_them","wx":"fog"},{"id":"e1090","day":29,"season":1,"sday":29,"kind":"wild_room","imp":3,"text":"Quill, frightened of the dark, counted the torches in the Ashveil Crypts three times and got three answers. The torches are not saying which was right.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","room":"wild_lamp_watcher","wx":"fog"},{"id":"e1091","day":29,"season":1,"sday":29,"kind":"fight","imp":1,"text":"It's a Bone Construct against the Amber Sigil in the articulator's hall on the deepest floor of the Ashveil Crypts, and it isn't close. Quill closed it out with Backstab on the bone construct. The Perfect Touch came over Sela at the right moment, as it does. Loot: 20 bones.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f69","foes":["bone_construct"],"where":"in the articulator's hall on the deepest floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-13,"wx":"fog"},{"id":"e1092","day":29,"season":1,"sday":29,"kind":"fight","imp":2,"text":"In the long gallery on the deepest floor of the Ashveil Crypts, 2 Skeleton Archers and 2 Risen Dead get in the Amber Sigil's way, briefly. After Sela's Perfect Touch, the risen dead hit like a tired farmhand. Loot: 9 bones, 5 grave dust, 4 remains.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f70","foes":["skeleton_archer","zombie","zombie"],"where":"in the long gallery on the deepest floor of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-15,"wx":"fog"},{"id":"e1093","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"The Ashveil Crypts, the deepest floor: five rooms for The Amber Sigil, at a hard pace. On the map now: the lamp-watcher's niche, the mourners' kitchen, the chaplain's cell and 2 more.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":5,"empty":0,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":2,"unwalked":0,"fights":2,"close":0,"gear":["common","common"],"fears":2,"wild":["wild_lamp_watcher"]},"wx":"fog"},{"id":"e1094","day":29,"season":1,"sday":29,"kind":"ambush","imp":2,"text":"In the middle of the night, 3 Skeletons find the Amber Sigil's camp on the deepest floor of the Ashveil Crypts, and the Amber Sigil defeats them. Perfect Touch, from Sela, was the last thing the skeleton saw. Quill's From the Rafters was the quiet reason it went their way. Sela kept the bleeding to a minimum. \"As I predicted,\" says Sela. Loot: 13 bones.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f71","foes":["skeleton","skeleton","skeleton"],"where":"at their camp on the deepest floor of The Ashveil Crypts, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-24,"wx":"fog"},{"id":"e1121","day":29,"season":1,"sday":29,"kind":"feud","imp":4,"text":"It's a feud: The Amber Sigil and Verdant Edge are sworn enemies, led by Quill and Ash. (4 heroes now hold grudges.)","heroes":["h11","h12","h17","h16"],"parties":["p3","p8"],"bond":"nemeses"},{"id":"e1122","day":29,"season":1,"sday":29,"kind":"bond","imp":2,"text":"The Amber Sigil and Verdant Edge are rivals now, starting with Sela and Ash. (3 heroes now hold grudges.)","heroes":["h2","h12","h17"],"parties":["p3","p8"],"bond":"rivals"},{"id":"e1123","day":29,"season":1,"sday":29,"kind":"pvp","imp":5,"text":"The Amber Sigil forces a surrender from Verdant Edge in the Ashveil Crypts and walks off with 53 silver. It isn't the first time: on day 17 of season 1, The Amber Sigil took 27 silver off Verdant Edge.","heroes":["h11","h2","h16","h12","h17"],"parties":["p3","p8"],"loc":"ashveil_crypts","fight":"f73","cause":"e653","losers":["h12","h17"],"wx":"fog"},{"id":"e1124","day":29,"season":1,"sday":29,"kind":"talent","imp":1,"text":"A rat lunges at Sela, misses, and is politely shown the door with the flat of a blade. Chalk it up to The Perfect Touch.","heroes":["h2"],"parties":["p3"],"loc":"ashveil_crypts","skill":"perfect_touch","wx":"fog"},{"id":"e1135","day":29,"season":1,"sday":29,"kind":"big_move","imp":3,"text":"The Amber Sigil forces a surrender from Verdant Edge in the Ashveil Crypts and walks off with 53 silver. On the table: The Amber Sigil +58 party renown (5th to 4th among the crews).","heroes":["h11","h2","h16"],"parties":["p3"],"party_moves":[{"party":"p3","gain":58,"from":5,"to":4}],"cause":"e1123","fight":"f73"},{"id":"e1143","day":30,"season":1,"sday":30,"kind":"party_life","imp":3,"text":"The Ashveil Crypts: Quill reached the third floor, sat down and offered to mind the bags. There were no bags to mind, and The Amber Sigil turns for the stairs regardless.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","refusal":"h11","wx":"fog"},{"id":"e1144","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts, 6 days on: The Amber Sigil comes up blinking at the daylight. They got all the way to the bottom, turned up the bell chamber, the funeral feast hall, the stitching room and 3 more good rooms, cleared 11 rooms, put 67% of it on paper, split 163 silver on the way up and turned back when one of them would go no further. Between every crew so far, the Ashveil Crypts is mostly explored (66%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","days":6,"bottom":true,"rooms":["the bell chamber","the funeral feast hall"],"gold":163,"turn":"refused","wx":"fog"},{"id":"e1164","day":30,"season":1,"sday":30,"kind":"meet","imp":1,"text":"Verdant Edge catches the sound of The Amber Sigil on the path outside the Ashveil Crypts and waits in the brush until it fades. Nobody needs a repeat of day 17 of season 1.","heroes":["h11","h2","h16","h12","h17"],"parties":["p3","p8"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1233","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"The Carrbridge smugglers pay their respects to Tamsin in the back room: 26 silver and the week's prices from three towns away.","heroes":["h16"],"parties":["p3"],"loc":"carrbridge","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true},{"id":"e1238","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"A month in The Amber Sigil together. Quill and Sela know each other's snores, sorrows and orders by heart.","heroes":["h11","h2"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1249","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Amber Sigil stands before the league and swears it: never to retreat. The Annals are watching.","heroes":["h11","h2","h16"],"parties":["p3"]},{"id":"e1266","day":32,"season":2,"sday":2,"kind":"night_game","imp":2,"text":"The bandit leaps from the roadside on the road to Ashfen, then stops, coughs and says, wait, wait, would anybody like a round of Crooked Cards instead? The bandit reads the final board three times, shrugs and hands Tamsin Bandit's Hidden Coin, saying it was meant to be a good one. Sela says they have seen worse ambushes, and the last one involved a goat.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashfen","night":"n84","monster_game":"bandit","wx":"fog"},{"id":"e1301","day":33,"season":2,"sday":3,"kind":"ambush","imp":2,"text":"The Amber Sigil gets the better of 3 Bandits and a Bandit Archer on the road to Ashfen. The last bandit breaks and runs. It was Sela's Second Intention that dropped the bandit. Look past the blows: Quill's From the Rafters was the difference. Loot: 14 silver each, 8 rations, 2 stolen goods.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f78","foes":["bandit","bandit_archer","bandit"],"where":"on the road to Ashfen","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e1318","day":33,"season":2,"sday":3,"kind":"argument","imp":2,"text":"The Amber Sigil spends the evening listening to Sela and Tamsin argue about whether ghosts can be bribed.","heroes":["h2","h16"],"parties":["p3"]},{"id":"e1319","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Quill aims an arrow at a far-off crow, misses on purpose, and gets a laugh out of Tamsin.","heroes":["h11","h16"],"parties":["p3"],"loc":"ashfen","wx":"fog"},{"id":"e1347","day":34,"season":2,"sday":4,"kind":"road","imp":2,"text":"Quill proposes splitting the disputed strip down the middle and putting a plum tree on the line. Both farmers grumble and agree, which is peace.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"ashfen~ashveil_crypts","road_rec":"r290"},{"id":"e1373","day":35,"season":2,"sday":5,"kind":"delve","imp":1,"text":"The Amber Sigil descends into the Ashveil Crypts, mostly explored (66%), map in hand.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1374","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"Two rooms on the deepest floor of the Ashveil Crypts for The Amber Sigil today: the iron-bound door, the Harrow vault.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":2,"empty":0,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1375","day":35,"season":2,"sday":5,"kind":"talent","imp":2,"text":"Quill practises on the crew's padlocks by firelight. Tamsin buys a better padlock. Chalk it up to Lockpicking.","heroes":["h11","h16"],"parties":["p3"],"loc":"ashveil_crypts","skill":"lockpicking","wx":"fog"},{"id":"e1393","day":36,"season":2,"sday":6,"kind":"ambush","imp":2,"text":"Two Bounty Hunters and the Bounty Hunters' Captain, sent for the price on Sela's head, catch up with the Amber Sigil in the Ashveil Crypts and regret it. Tamsin put Thorn Whip into the Bounty Hunters' Captain to end it, and lowered the bow. Sela's The Perfect Touch picked its moment well. Tamsin touched the coin in her pocket at the worst moment. The moment passed. \"That's a bonus, that is,\" says Tamsin. Loot: 53 silver each, 6 stolen goods, 4 bandit sausages.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f83","foes":["bandit_captain","bandit","bandit"],"where":"in The Ashveil Crypts, sent for the price on Sela's head","won":true,"close":false,"shape":"hunted","reworded":-25,"wx":"fog"},{"id":"e1395","day":36,"season":2,"sday":6,"kind":"fight","imp":2,"text":"Quill hits hardest as the Amber Sigil makes short work of 2 Risen Dead and 2 Wraiths in the threshold of the lowest crypt on the deepest floor of the Ashveil Crypts. Quill's Fire Arrow finished the fight. Quill's From the Rafters kicked in when it counted. Loot: 6 grave dust, 3 crypt-caps, 5 ectoplasm.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f84","foes":["zombie","wraith","zombie"],"where":"in the threshold of the lowest crypt on the deepest floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-22,"wx":"fog"},{"id":"e1396","day":36,"season":2,"sday":6,"kind":"fight","imp":2,"text":"Three Risen Dead and a Skeleton stir in the ossuary on the deepest floor of the Ashveil Crypts, and the Amber Sigil handles them for good. The final blow was Sela's Smite. Loot: 6 crypt-caps, 5 bones, 3 trinkets.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f85","foes":["zombie","zombie","skeleton"],"where":"in the ossuary on the deepest floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-28,"wx":"fog"},{"id":"e1397","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The deepest floor of the Ashveil Crypts, taken one door at a time: The Amber Sigil gets through four rooms (the grave-goods heap, the threshold of the lowest crypt, the ossuary and 1 more).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"empty":0,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":2,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1430","day":37,"season":2,"sday":7,"kind":"boss","imp":5,"text":"At the bottom of the Ashveil Crypts, it's over: the Amber Sigil brings down Vessimir the Unburied, Risen Dead and a Bone Construct. The risen dead went down to Quill's Snare. Sela's Lunge caught it square. It stayed down. Sela's The Perfect Touch turned the fight. Without Tamsin's Trip Wire, this goes differently. Loot: 105 silver each, 14 ectoplasm, 15 grave dust.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f88","foes":["necromancer","zombie","bone_construct"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":1},{"id":"e1431","day":37,"season":2,"sday":7,"kind":"treasure","imp":2,"text":"Behind the seat where Vessimir the Unburied held court lies the hoard: 11 gold pieces and 6 silver, counted twice to be sure.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","in_fight":"f88"},{"id":"e1432","day":37,"season":2,"sday":7,"kind":"gear","imp":4,"text":"A pale mask with a calm, sleeping face from the lowest crypt leaves the dark of the Ashveil Crypts in Quill's pack. There isn't another. What it can do is anyone's guess until a town names it.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1433","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The necromancer's workroom, the last cortege, the lowest crypt: the day's work on the deepest floor of the Ashveil Crypts for The Amber Sigil, taken steadily.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"empty":0,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":0,"wild":[]}},{"id":"e1434","day":37,"season":2,"sday":7,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts hands The Amber Sigil back after 3 days, dusty and squinting. They reached the deepest floor, cleared 9 rooms, turned up the Harrow vault, the grave-goods heap, the ossuary and 2 more good rooms, put 83% of it on paper and came away with 796 silver between them. Pin it to the board: The Ashveil Crypts is mostly explored (81%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts","days":3,"bottom":true,"rooms":["the Harrow vault","the grave-goods heap"],"gold":796,"turn":"done"},{"id":"e1435","day":37,"season":2,"sday":7,"kind":"talent","imp":1,"text":"Sela practises one thrust a thousand times by the fire, then sits down, satisfied. That's The Perfect Touch for you.","heroes":["h2"],"parties":["p3"],"loc":"ashveil_crypts","skill":"perfect_touch"},{"id":"e1457","day":37,"season":2,"sday":7,"kind":"campfire","imp":2,"text":"Quill and Tamsin see in a month of The Amber Sigil by splitting the last good bottle. Nobody else is offered any.","heroes":["h11","h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1458","day":37,"season":2,"sday":7,"kind":"campfire","imp":1,"text":"Thirty days in The Amber Sigil. Sela and Tamsin have stopped keeping score of who owes whom.","heroes":["h2","h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1467","day":37,"season":2,"sday":7,"kind":"big_move","imp":3,"text":"At the bottom of the Ashveil Crypts, it's over: the Amber Sigil brings down Vessimir the Unburied, Risen Dead and a Bone Construct. On the table: The Amber Sigil +96 party renown (holds 2nd among the crews).","heroes":["h11","h2","h16"],"parties":["p3"],"party_moves":[{"party":"p3","gain":96,"from":1,"to":2}],"cause":"e1430","fight":"f88"},{"id":"e1472","day":38,"season":2,"sday":8,"kind":"party_life","imp":1,"text":"By the third crossroads Quill has stopped waiting and started complaining about the wait.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1539","day":39,"season":2,"sday":9,"kind":"road","imp":3,"text":"Quill is surprised to find a ridge on Ines's map marked with his own name. She has been drawing it all week.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"ashfen~carrbridge","traveller":"ines","road_rec":"r316"},{"id":"e1548","day":39,"season":2,"sday":9,"kind":"talent","imp":2,"text":"Sela spends the walk teaching Tamsin to step back after a good hit, not forward.","heroes":["h2","h16"],"parties":["p3"],"loc":"ashfen","skill":"perfect_touch"},{"id":"e1575","day":40,"season":2,"sday":10,"kind":"road","imp":3,"text":"A jar of silver turns up in a landslip by the road to Carrbridge. Tamsin finds the owner's note in it, a hundred years old, asking whoever finds it to spend it kindly, and mentioning Cragtooth Warren.","heroes":["h16","h11","h2"],"parties":["p3"],"road":"ashfen~carrbridge","road_rec":"r325"},{"id":"e1596","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"Tamsin walks the dark side of the road so Sela doesn't have to, and never says why.","heroes":["h16","h2"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1645","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Tamsin spins the hollow coin on a log and listens to it rattle.","heroes":["h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e1650","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Amber Sigil's plan for the season, as told to the barkeep: to finish the season as one of the top three parties.","heroes":["h11","h2","h16"],"parties":["p3"]},{"id":"e1665","day":42,"season":2,"sday":12,"kind":"fight","imp":2,"text":"The Amber Sigil gets the better of 3 Bandits and a Bandit Archer on the King's Road. Thorn Whip, from Tamsin, was the last thing the bandit saw. From the Rafters came over Quill at the right moment, as it does. Loot: 16 silver each, 5 stolen goods, 9 rations.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f96","foes":["bandit","bandit","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"plain","reworded":-9},{"id":"e1687","day":42,"season":2,"sday":12,"kind":"talent","imp":2,"text":"Sela whittles a tiny wolf for Tamsin by the fire. Tamsin calls it silly and keeps it in a breast pocket.","heroes":["h2","h16"],"parties":["p3"],"loc":"kingsroad","skill":"whittler"},{"id":"e1695","day":43,"season":2,"sday":13,"kind":"hunt","imp":3,"text":"Quill, Tamsin and Sela did what the villages said nobody would: the Old Boar of the King's Road, taken.","heroes":["h16","h11","h2"],"parties":["p3"],"loc":"kingsroad","named":"old_boar","road_rec":"r348"},{"id":"e1696","day":43,"season":2,"sday":13,"kind":"hunt","imp":4,"text":"The King's Road: Sela skins the old boar by the fire in one piece, and lays the hide out, and nobody speaks. It is bigger than a bed, and every scar on it is a story.","heroes":["h2","h11","h16"],"parties":["p3"],"loc":"kingsroad","road_rec":"r349"},{"id":"e1714","day":43,"season":2,"sday":13,"kind":"talent","imp":1,"text":"Quill stops at a wayside grave to say the words for a stranger. It takes a minute. It matters. A small Vigil, cast without looking up.","heroes":["h11"],"parties":["p3"],"loc":"kingsroad","skill":"vigil"},{"id":"e1728","day":44,"season":2,"sday":14,"kind":"road","imp":3,"text":"Nib presses a spoon into Sela's hand with great ceremony. It is the best spoon in the Pack, and it is yours now, for ever.","heroes":["h2","h11","h16"],"parties":["p3"],"road":"ironhaven~kingsroad","traveller":"muddy_boot","road_rec":"r356"},{"id":"e1755","day":44,"season":2,"sday":14,"kind":"campfire","imp":2,"text":"Sela talks Quill through a bad night about beasts. Neither mentions it in the morning. Both remember.","heroes":["h2","h11"],"parties":["p3"],"loc":"ironhaven"},{"id":"e1830","day":47,"season":2,"sday":17,"kind":"ability","imp":2,"text":"Tamsin orders a drink in a Frosthold tavern and the barman pours it with a folded note underneath: 26 silver, and what the docks upriver will pay for wool next week.","heroes":["h16"],"parties":["p3"],"loc":"frosthold","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true},{"id":"e1836","day":47,"season":2,"sday":17,"kind":"argument","imp":2,"text":"Quill says one thing too many about Quill's habit of humming during ambushes. Sela says two.","heroes":["h11","h2"],"parties":["p3"]},{"id":"e1904","day":49,"season":2,"sday":19,"kind":"tarot","imp":2,"text":"On the last night before Frostspire, Sela spreads a cloak by the fire and reads the Bog-Warped Tarot for the whole of The Amber Sigil: the Page of Wands, the Empress and the Page of Cups. Nothing to worry about, says Sela.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","reading":"r398"},{"id":"e1931","day":50,"season":2,"sday":20,"kind":"delve","imp":1,"text":"The Amber Sigil descends into Frostspire, barely touched (7%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire"},{"id":"e1933","day":50,"season":2,"sday":20,"kind":"fight","imp":1,"text":"Three Frost Wolves make the mistake of going for the Amber Sigil in the wolf run on the first floor of Frostspire. The last frost wolf takes off and isn't seen again. Somewhere around Quill's Never Where You Left Them, the other side stopped believing. Sela kept them off everyone with The Perfect Touch. Loot: 12 pelts, 3 wolf haunches, 5 fangs & claws.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f113","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"in the wolf run on the first floor of Frostspire","won":true,"close":false,"shape":"foe","reworded":-51},{"id":"e1934","day":50,"season":2,"sday":20,"kind":"delve_day","imp":1,"text":"Down in Frostspire, The Amber Sigil maps eight rooms of the first floor, steadily (the cairn of the turned-back, the icicle porch, the wrecked sledge and 5 more).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":8,"empty":6,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e1964","day":51,"season":2,"sday":21,"kind":"fight","imp":2,"text":"Quill hits hardest as the Amber Sigil dispatches 2 Ice Golems and an Ice Wraith in the frozen guardroom on the first floor of Frostspire. Everything after Quill's Backstab went right. Loot: 4 wraith-frost, 6 frost crystals.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f116","foes":["ice_wraith","ice_golem","ice_golem"],"where":"in the frozen guardroom on the first floor of Frostspire","won":true,"close":false,"shape":"hero","reworded":-22},{"id":"e1965","day":51,"season":2,"sday":21,"kind":"fight","imp":2,"text":"In the yeti's larder on the first floor of Frostspire, the Amber Sigil sees off 2 Frost Wolves and a Yeti. Sela's Perfect Touch knocked half the fight out of the frost wolf. Loot: 15 pelts, 4 yeti steaks, 3 fangs & claws.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f117","foes":["yeti","frost_wolf","frost_wolf"],"where":"in the yeti's larder on the first floor of Frostspire","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e1966","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"The Amber Sigil works the first floor of Frostspire at a cautious pace: three rooms (the ice gate, the frozen guardroom, the yeti's larder).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","pace":"cautious","stats":{"rooms":3,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":4,"wild":[]}},{"id":"e1979","day":51,"season":2,"sday":21,"kind":"campfire","imp":2,"text":"Sela and Tamsin take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h2","h16"],"parties":["p3"],"loc":"frostspire"},{"id":"e1991","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Amber Sigil pushes on through the first floor of Frostspire carefully. Three rooms by nightfall: the sentries' bunks, the buried trunks, the clear-ice room.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","pace":"cautious","stats":{"rooms":3,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2020","day":53,"season":2,"sday":23,"kind":"fight","imp":2,"text":"The Amber Sigil sees off 3 Yetis and a Frost Wolf in a slope of packed snow that winds up the inside of the tower on the first floor of Frostspire. Tamsin put Thorn Whip into the yeti to end it, and lowered the bow. Loot: 30 pelts, 3 wolf haunches, 1 frost crystal.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f120","foes":["frost_wolf","yeti","yeti"],"where":"in a slope of packed snow that winds up the inside of the tower on the first floor of Frostspire","won":true,"close":false,"shape":"plain"},{"id":"e2021","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"The Amber Sigil tallies up the first floor of Frostspire at nightfall: three rooms, taken at a steady pace, and the names go in the book (the white chapel, a slope of packed snow that winds up the inside of the tower, the sentry stair).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"empty":0,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2025","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Sela jams a trap's gears at Frostspire with a hairpin and a prayer. The crew walks past it. (Tinkerer, if anyone's asking.)","heroes":["h2"],"parties":["p3"],"loc":"frostspire","skill":"tinkerer"},{"id":"e2040","day":54,"season":2,"sday":24,"kind":"fight","imp":2,"text":"The Amber Sigil, in fine spirits lately, dispatches 4 Frost Wolves in the hall of blue ice on the first floor of Frostspire. The hit of the day was Sela's Perfect Touch on the frost wolf. Loot: 25 pelts, 12 fangs & claws, 5 wolf haunches.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f121","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"in the hall of blue ice on the first floor of Frostspire","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2041","day":54,"season":2,"sday":24,"kind":"fight","imp":1,"text":"It's an Ice Golem against the Amber Sigil in the golem's niche on the first floor of Frostspire, and it isn't close. The fight was over the moment Sela's Second Intention landed on the ice golem. Loot: 4 frost crystals.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f122","foes":["ice_golem"],"where":"in the golem's niche on the first floor of Frostspire","won":true,"close":false,"shape":"foe","reworded":-24},{"id":"e2044","day":54,"season":2,"sday":24,"kind":"fight","imp":2,"text":"With Sela hitting hardest, the Amber Sigil cuts down 3 Frost Wolves and 2 Yetis in the yeti's meat hall on the first floor of Frostspire. Ask anyone when it turned: Sela's Cleave. Ask the others what won it: Sela's The Perfect Touch. Loot: 37 pelts, 13 fangs & claws, 5 wolf haunches.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","fight":"f123","foes":["yeti","frost_wolf","yeti"],"where":"in the yeti's meat hall on the first floor of Frostspire","won":true,"close":false,"shape":"hero","reworded":-27},{"id":"e2045","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"The Amber Sigil spends the day on the first floor of Frostspire, at a hard pace, and covers four rooms: the hall of blue ice, the golem's niche, the lens hall and 1 more.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":4,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":3,"close":0,"gear":["common"],"fears":4,"wild":[]}},{"id":"e2046","day":54,"season":2,"sday":24,"kind":"night","imp":2,"text":"Quill's ghost story on the first floor of Frostspire goes on too long and never really ends. Sela lies awake waiting for the ending.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire"},{"id":"e2097","day":55,"season":2,"sday":25,"kind":"party_life","imp":3,"text":"Frostspire won on the first floor, when Quill said no, quietly, and The Amber Sigil turns round to agree.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","refusal":"h11"},{"id":"e2098","day":55,"season":2,"sday":25,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 6 days, and The Amber Sigil comes out into it shading every eye. They reached the first floor, took 15 rooms off the map's blank side, turned up the hunters' shrine, the buried trunks, the white chapel and 1 more good room, mapped 25% of it, came away with 145 silver between them and turned back when one of them would go no further. The guild's map has it: Frostspire is mostly unexplored (27%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"frostspire","days":6,"bottom":false,"rooms":["the hunters' shrine","the buried trunks"],"gold":145,"turn":"refused"},{"id":"e2105","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Tamsin roots a bramble in a crack by the dungeon door. It will be waiting on the way out. Tamsin puts it down to Bramble Ground.","heroes":["h16"],"parties":["p3"],"loc":"frostspire","skill":"bramble_ground"},{"id":"e2120","day":56,"season":2,"sday":26,"kind":"road","imp":3,"text":"Tamsin sits with a hooded pilgrim by the Snow Lamp and shares bread, and the pilgrim murmurs a blessing in a tongue Tamsin nearly understands. She leaves 2 copper in the tin.","heroes":["h16","h11","h2"],"parties":["p3"],"road":"frostspire~whitepeak","road_rec":"r439"},{"id":"e2121","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Sela wakes to find Quill already on watch. Sela never saw him get up.","heroes":["h11","h2"],"parties":["p3"],"loc":"whitepeak","skill":"shadow_of_death","wx":"snow"},{"id":"e2135","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Tamsin plaits a bramble fence round the camp. It keeps out the deer and, on one occasion, Sela. (Bramble Ground, if anyone's asking.)","heroes":["h16","h2"],"parties":["p3"],"loc":"whitepeak","skill":"bramble_ground","wx":"snow"},{"id":"e2173","day":57,"season":2,"sday":27,"kind":"feud","imp":4,"text":"It's a feud: The Amber Sigil and Gilded Wall are sworn enemies, led by Quill and Gorm. (4 heroes now hold grudges.)","heroes":["h11","h9","h6","h16"],"parties":["p3","p6"],"bond":"nemeses"},{"id":"e2174","day":57,"season":2,"sday":27,"kind":"bond","imp":3,"text":"The Amber Sigil and Gilded Wall are rivals now, starting with Sela and Tobias.","heroes":["h2","h6"],"parties":["p3","p6"],"bond":"rivals"},{"id":"e2175","day":57,"season":2,"sday":27,"kind":"pvp","imp":5,"text":"The Amber Sigil flattens Gilded Wall on the road between Frosthold and Whitepeak Pass after a robbery goes wrong and walks off with 25 silver.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"frosthold","fight":"f128","losers":["h9","h6"],"wx":"snow"},{"id":"e2179","day":57,"season":2,"sday":27,"kind":"ability","imp":2,"text":"Three separate strangers in Frosthold buy Tamsin a drink tonight. Each leaves a coin or two and a whisper about prices. 26 silver all told.","heroes":["h16"],"parties":["p3"],"loc":"frosthold","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true,"wx":"snow"},{"id":"e2184","day":57,"season":2,"sday":27,"kind":"big_move","imp":3,"text":"The Amber Sigil flattens Gilded Wall on the road between Frosthold and Whitepeak Pass after a robbery goes wrong and walks off with 25 silver. On the table: The Amber Sigil +50 party renown (holds 2nd among the crews).","heroes":["h11","h2","h16"],"parties":["p3"],"party_moves":[{"party":"p3","gain":50,"from":2,"to":2}],"cause":"e2175","fight":"f128"},{"id":"e2198","day":58,"season":2,"sday":28,"kind":"road","imp":2,"text":"A loose pony in a halter trots up beside Gerald on the road to Veldrock. Sela leads it a mile down a lane to the farm it plainly came from, and the farmwife is so grateful that a bag of oatcakes is pressed into Sela's hands.","heroes":["h2","h11","h16"],"parties":["p3"],"road":"frosthold~veldrock","road_rec":"r465"},{"id":"e2216","day":58,"season":2,"sday":28,"kind":"talent","imp":1,"text":"Tamsin tucks a sprig of thorn into every gatepost on the road, for later.","heroes":["h16"],"parties":["p3"],"loc":"frosthold","skill":"bramble_ground","wx":"snow"},{"id":"e2222","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Sela and Tamsin start a running tally of who saved whom. It is currently tied, and disputed.","heroes":["h2","h16"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e2234","day":59,"season":2,"sday":29,"kind":"bounty","imp":2,"text":"The Amber Sigil cashes in a season's worth of trophies at the Veldrock guild: about 98 silver a head.","heroes":["h11"],"parties":["p3"],"loc":"veldrock","amount":98},{"id":"e2237","day":59,"season":2,"sday":29,"kind":"gift","imp":2,"text":"Sela hands their old Peacock Cap to Tamsin, who has been eyeing it for a week.","heroes":["h2","h16"],"parties":["p3"],"loc":"veldrock"},{"id":"e2298","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Amber Sigil set out to finish the season as one of the top three parties, and the final table says they made it. XP: Quill +800 (level 21!), Sela +800 (level 21!), Tamsin +800.","heroes":[],"parties":["p3"],"xp":{"h11":800,"h2":800,"h16":800}},{"id":"e2367","day":61,"season":3,"sday":1,"kind":"campfire","imp":1,"text":"Sela walks the dark side of the road so Quill doesn't have to, and never says why.","heroes":["h2","h11"],"parties":["p3"],"loc":"carrbridge","wx":"heat"},{"id":"e2388","day":62,"season":3,"sday":2,"kind":"map_bought","imp":2,"text":"The Amber Sigil buys a map of the Sunken Vault in Carrbridge for 64 silver, drawn by Wren. The place is partly explored (36%).","heroes":["h11","h2","h16","h20"],"parties":["p3"],"loc":"carrbridge","wx":"heat"},{"id":"e2393","day":62,"season":3,"sday":2,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Amber Sigil and Gilded Wall are both after The Kraken of the Vault. The Sunken Vault has one way down and room for one winner.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e2425","day":64,"season":3,"sday":4,"kind":"ambush","imp":2,"text":"In thick fog, the Amber Sigil sees off 2 Bandits on the road to Saltmarrow. Sela finished the bandit with Perfect Touch and leaned on their weapon, breathing hard. Quill kept them off everyone with From the Rafters. The enemy swung at where Quill seemed to be. Quill was a little to the left. Loot: 8 silver each, 4 stolen goods, a string of bandit sausages.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f140","foes":["bandit","bandit"],"where":"on the road to Saltmarrow","won":true,"close":false,"shape":"weather","reworded":-14,"wx":"fog"},{"id":"e2448","day":64,"season":3,"sday":4,"kind":"talent","imp":2,"text":"A Saltmarrow merchant crosses the street to avoid Tamsin, then crosses back to offer a discount.","heroes":["h16"],"parties":["p3"],"loc":"saltmarrow","skill":"underworld_royalty","wx":"fog"},{"id":"e2449","day":64,"season":3,"sday":4,"kind":"ability","imp":2,"text":"Tamsin spends the evening in a Saltmarrow back room being told things. Nobody in the tavern sees her come or go, but she leaves with 53 silver and the prices from three markets.","heroes":["h16"],"parties":["p3"],"loc":"saltmarrow","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true,"wx":"fog"},{"id":"e2463","day":65,"season":3,"sday":5,"kind":"ambush","imp":2,"text":"On the road to the Salt Cliffs, the Amber Sigil handles the Bounty Hunters' Captain and Bounty Hunter, sent for the price on Tamsin's head. Ask anyone when it turned: Sela's Perfect Touch. Tamsin finished it, quietly, while the others were still catching their breath. Loot: 44 silver each, 6 stolen goods, 3 bandit sausages.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"saltcliffs","fight":"f144","foes":["bandit_captain","bandit"],"where":"on the road to The Salt Cliffs, sent for the price on Tamsin's head","won":true,"close":false,"shape":"hunted","reworded":-1,"wx":"fog"},{"id":"e2464","day":65,"season":3,"sday":5,"kind":"night","imp":2,"text":"Something small and clever gets into The Amber Sigil's camp in the Salt Cliffs overnight. Sela wakes up 8 silver and 1 ration lighter.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"saltcliffs","wx":"fog"},{"id":"e2496","day":66,"season":3,"sday":6,"kind":"ambush","imp":2,"text":"On the road to the Sunken Vault, the Amber Sigil squares up to 2 Bandits and carries the day. The last bandit is gone before anyone can stop it. Before Quill's Never Where You Left Them it could have gone either way. Without Quill's From the Rafters, this goes differently. Last Word, grandmother's sword, did what it has always done. \"Applause is customary,\" says Sela. Loot: 6 silver each, 3 stolen goods, a string of bandit sausages.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"saltcliffs","fight":"f149","foes":["bandit","bandit"],"where":"on the road to The Sunken Vault","won":true,"close":false,"shape":"place","reworded":-55,"wx":"fog"},{"id":"e2519","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Sela practises footwork round the fire until Tamsin gets dizzy watching. Somebody asks how. 'Blade Dancer,' says Sela.","heroes":["h2","h16"],"parties":["p3"],"loc":"sunken_vault","skill":"blade_dancer","wx":"fog"},{"id":"e2528","day":67,"season":3,"sday":7,"kind":"delve","imp":1,"text":"The Amber Sigil descends into the Sunken Vault, partly explored (38%), map in hand.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault"},{"id":"e2529","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"The bullion cellar, the guards' mess, the coin vaults and 1 more: the day's work on the second floor of the Sunken Vault for The Amber Sigil, taken without hurrying.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"empty":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2565","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Amber Sigil keeps at the third floor of the Sunken Vault at speed, four rooms deep in the day: the sea stairs, green to the waterline, the deposit boxes, the clerks' desks and 1 more.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault","pace":"push","stats":{"rooms":4,"empty":4,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2580","day":68,"season":3,"sday":8,"kind":"meet","imp":2,"text":"A scout's whistle, a quick detour: Gilded Wall leaves The Amber Sigil the road outside the Sunken Vault. Day 27 of season 2 taught them which camps to avoid.","heroes":["h9","h6","h11","h2","h16"],"parties":["p6","p3"],"loc":"sunken_vault"},{"id":"e2581","day":68,"season":3,"sday":8,"kind":"gift","imp":2,"text":"By the fire, Quill quietly hands Tamsin a Kobold Whistle. Tamsin pockets it like it's treasure.","heroes":["h11","h16"],"parties":["p3"],"loc":"sunken_vault"},{"id":"e2583","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Tamsin briefs the crew on which other parties are feuding, and why. Sela takes notes. Rumourmonger: one of the things Tamsin learned the long way round.","heroes":["h16","h2"],"parties":["p3"],"loc":"sunken_vault","skill":"rumourmonger"},{"id":"e2584","day":68,"season":3,"sday":8,"kind":"campfire","imp":1,"text":"Sela finds a soggy ledger and reads Tamsin the worst debts in it in a banker's voice.","heroes":["h16","h2"],"parties":["p3"],"loc":"sunken_vault"},{"id":"e2606","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Amber Sigil gives the third floor of the Sunken Vault another day, carefully, and four rooms give way (the tide-pool chapel, the rusted keyhole door, the queue for teller nine and 1 more).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":4,"empty":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2609","day":69,"season":3,"sday":9,"kind":"meet","imp":2,"text":"The Amber Sigil and The Sunlit Almanac cross paths in the Sunken Vault. Nobody draws, but nobody turns their back either.","heroes":["h11","h2","h16","h8","h20","h18","h19"],"parties":["p3","p4"],"loc":"sunken_vault"},{"id":"e2610","day":69,"season":3,"sday":9,"kind":"gift","imp":2,"text":"By the fire, Sela quietly hands Quill a Troll's Tooth. Quill pockets it like it's treasure.","heroes":["h2","h11"],"parties":["p3"],"loc":"sunken_vault"},{"id":"e2629","day":70,"season":3,"sday":10,"kind":"delve_day","imp":1,"text":"Torch by torch through the third floor of the Sunken Vault, The Amber Sigil makes it through one room, at a steady pace: the cracked foundation.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"empty":0,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"rain"},{"id":"e2630","day":70,"season":3,"sday":10,"kind":"delve_done","imp":1,"text":"After 4 days underground, The Amber Sigil climbs back into the open air, gulping it down like water. They never got past the way in, put 53% of it on paper and turned back because the way on beat them twice, and they mean to come back with more. The Sunken Vault, all crews together: partly explored (47%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"sunken_vault","days":4,"bottom":false,"rooms":[],"gold":0,"turn":"blocked","wx":"rain"},{"id":"e2647","day":70,"season":3,"sday":10,"kind":"meet","imp":1,"text":"The Sunlit Almanac and The Amber Sigil are still camped within sight of each other outside the Sunken Vault. A second night of not talking, kept up with real dedication.","heroes":["h8","h20","h18","h19","h11","h2","h16"],"parties":["p4","p3"],"loc":"sunken_vault","wx":"rain"},{"id":"e2678","day":71,"season":3,"sday":11,"kind":"ambush","imp":2,"text":"The Amber Sigil runs into 4 Cliff Crabs on the road to the Salt Cliffs and comes out on top. The last cliff crab breaks and runs. Sela's Second Intention took most of the fight out of the cliff crab in one go. The Perfect Touch came over Sela at the right moment, as it does. Quill was already counting the loot before the last one fell. \"More,\" says Quill. Loot: 9 chitin, 8 cliff crab claws, 3 fish.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"saltcliffs","fight":"f162","foes":["crab","crab","crab"],"where":"on the road to The Salt Cliffs","won":true,"close":false,"shape":"plain","reworded":-35,"wx":"rain"},{"id":"e2679","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Sela bets Tamsin a silver that Tamsin can't touch Sela's sleeve with a stick. Tamsin tries for an hour.","heroes":["h2","h16"],"parties":["p3"],"loc":"saltcliffs","skill":"wager_of_honour","wx":"rain"},{"id":"e2683","day":71,"season":3,"sday":11,"kind":"journey","imp":2,"text":"The Sunlit Almanac and The Amber Sigil fall in together on the road to the Salt Cliffs and spend the miles arguing about the best way to cook a rat.","heroes":["h8","h20","h18","h19","h11","h2","h16"],"parties":["p4","p3"]},{"id":"e2699","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Amber Sigil's plan for the season, as told to the barkeep: to earn 3,100 silver between them before the season ends.","heroes":["h11","h2","h16"],"parties":["p3"]},{"id":"e2712","day":72,"season":3,"sday":12,"kind":"road","imp":2,"text":"Quill and Edda Dunmore cross the Gannet ferry through a squall, and arrive on the far side soaked, laughing and unsunk.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"saltcliffs~saltmarrow","road_rec":"r570"},{"id":"e2738","day":72,"season":3,"sday":12,"kind":"ability","imp":2,"text":"The Saltmarrow smugglers pay their respects to Tamsin in the back room: 43 silver and the week's prices from three towns away.","heroes":["h16"],"parties":["p3"],"loc":"saltmarrow","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true,"wx":"rain"},{"id":"e2742","day":72,"season":3,"sday":12,"kind":"argument","imp":4,"text":"Quill and Sela have had the same argument three times now. This time Quill just walks away mid-sentence, which is worse. The Amber Sigil is splitting into camps.","heroes":["h11","h2"],"parties":["p3"]},{"id":"e2753","day":73,"season":3,"sday":13,"kind":"road","imp":3,"text":"Mags Halloran shares a fire with Sela and, for once, a rumour: something is stirring in the Sunken Vault.","heroes":["h2","h11","h16"],"parties":["p3"],"road":"carrbridge~saltmarrow","traveller":"mags","road_rec":"r584"},{"id":"e2784","day":73,"season":3,"sday":13,"kind":"campfire","imp":1,"text":"Sela grumbles about Tamsin's cooking all through supper and has seconds.","heroes":["h16","h2"],"parties":["p3"],"loc":"saltmarrow","wx":"rain"},{"id":"e2832","day":74,"season":3,"sday":14,"kind":"ledger","imp":2,"text":"The week's trade: 19 packs emptied onto counters for 1,395 silver. Biggest haul: Wren, 174 silver in Carrbridge. Back up from the deep: The Amber Sigil (4 days in the Sunken Vault).","heroes":["h20","h11"],"parties":["p3"]},{"id":"e2867","day":75,"season":3,"sday":15,"kind":"campfire","imp":2,"text":"Quill aims an arrow at a far-off crow, misses on purpose, and gets a laugh out of Sela.","heroes":["h11","h2"],"parties":["p3"],"loc":"carrbridge"},{"id":"e2930","day":77,"season":3,"sday":17,"kind":"talent","imp":1,"text":"Sela stops by a stream near Ironhaven to re-temper a blade in the cold water. It hisses like a cat.","heroes":["h2"],"parties":["p3"],"loc":"ironhaven","skill":"field_forge","wx":"rain"},{"id":"e2939","day":78,"season":3,"sday":18,"kind":"road","imp":2,"text":"Granfer Oake wags a stick at the clouds for the first time as Tamsin approaches and says that this lot are up to something.","heroes":["h16","h11","h2"],"parties":["p3"],"road":"ironhaven~veldrock","traveller":"oake","road_rec":"r627"},{"id":"e2951","day":78,"season":3,"sday":18,"kind":"boss_race","imp":3,"text":"A race for Cindervast the Hoardmother: The Amber Sigil and Gilded Wall are all bound for Emberdeep. Only one of them gets the kill.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2959","day":78,"season":3,"sday":18,"kind":"talent","imp":1,"text":"Quill sells three fox traps to a Veldrock poultry farmer before breakfast and takes an order for two more. That's Trap Seller for you.","heroes":["h11"],"parties":["p3"],"loc":"veldrock","skill":"trap_seller","wx":"snow"},{"id":"e2964","day":78,"season":3,"sday":18,"kind":"argument","imp":2,"text":"The Amber Sigil spends the evening listening to Quill and Sela argue about whose idea the last dungeon was.","heroes":["h11","h2"],"parties":["p3"]},{"id":"e3004","day":79,"season":3,"sday":19,"kind":"argument","imp":1,"text":"Tamsin and Quill spend supper disagreeing about the ethics of looting bodies, politely at first.","heroes":["h16","h11"],"parties":["p3"]},{"id":"e3034","day":80,"season":3,"sday":20,"kind":"road","imp":2,"text":"Quill shares his rations at the Pitmen's Rest with a hungry miner, and is paid back with a lump of good ore and the tale of its finding.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"emberdeep~veldrock","road_rec":"r651"},{"id":"e3038","day":80,"season":3,"sday":20,"kind":"meet","imp":1,"text":"Gilded Wall and The Amber Sigil make camp outside Emberdeep on opposite sides of one clearing. Each side posts a watch, and the two watches stare at each other till dawn.","heroes":["h9","h6","h11","h2","h16"],"parties":["p6","p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3041","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Sela steps neatly round a pressure plate without even looking down. (Blade Dancer, if anyone's asking.)","heroes":["h2"],"parties":["p3"],"loc":"emberdeep","skill":"blade_dancer","wx":"snow"},{"id":"e3044","day":80,"season":3,"sday":20,"kind":"tarot","imp":2,"text":"Nobody sleeps until Sela has read for The Amber Sigil. The night before Emberdeep, three cards: the Six of Swords, the Empress and the Three of Wands upside down. Sela taps the middle card and says nothing.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","reading":"r655","wx":"snow"},{"id":"e3063","day":81,"season":3,"sday":21,"kind":"delve","imp":1,"text":"The Amber Sigil descends into Emberdeep, barely touched (5%).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3064","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"The Amber Sigil pushes on through the first floor of Emberdeep at speed. Six rooms by nightfall: the cairn of the unlucky, the gate-wards, the dwarven watch-room and 3 more.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","pace":"push","stats":{"rooms":6,"empty":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3081","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"Sela counts the tally marks on the goblin's spoon again. Forty-one. They don't know of what.","heroes":["h2"],"parties":["p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3097","day":82,"season":3,"sday":22,"kind":"wild_room","imp":3,"text":"Quill took a corner in an ore cart in Emberdeep on two wheels, then on none. The corner was unharmed.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","room":"wild_ore_cart_run"},{"id":"e3098","day":82,"season":3,"sday":22,"kind":"wild_room","imp":3,"text":"Sela took a corner in an ore cart in Emberdeep on two wheels, then on none. The corner was unharmed.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","room":"wild_ore_cart_run"},{"id":"e3099","day":82,"season":3,"sday":22,"kind":"delve_day","imp":1,"text":"Deeper into the first floor of Emberdeep: The Amber Sigil sees four rooms today, at a hard pace (the ore track, the ore track, the surveyors' office and 1 more).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","pace":"push","stats":{"rooms":4,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":4,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_ore_cart_run","wild_ore_cart_run"]}},{"id":"e3100","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Tamsin cleans a find with a soft brush and patience, and the crest of a forgotten house appears.","heroes":["h16"],"parties":["p3"],"loc":"emberdeep","skill":"relic_lore"},{"id":"e3119","day":82,"season":3,"sday":22,"kind":"meet","imp":2,"text":"The Amber Sigil and The Sunlit Almanac end up at the same fire outside Emberdeep. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h11","h2","h16","h8","h20","h18","h19"],"parties":["p3","p4"],"loc":"emberdeep"},{"id":"e3137","day":83,"season":3,"sday":23,"kind":"fight","imp":2,"text":"Two Fire Elementals and a Salamander fall to the Amber Sigil in a ramp of black glass beside the lava-fall on the first floor of Emberdeep. It was Sela's Blade Dancer that dropped the fire elemental. Loot: 4 ember cores, 1 drake scale, 5 salamander tails.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","fight":"f176","foes":["fire_elemental","salamander","fire_elemental"],"where":"in a ramp of black glass beside the lava-fall on the first floor of Emberdeep","won":true,"close":false,"shape":"foe","wx":"storm"},{"id":"e3138","day":83,"season":3,"sday":23,"kind":"delve_day","imp":1,"text":"The Amber Sigil works the first floor of Emberdeep at a cautious pace: three rooms (a ramp of black glass beside the lava-fall, the ice cellar, the mint vault).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","pace":"cautious","stats":{"rooms":3,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common","common"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e3151","day":83,"season":3,"sday":23,"kind":"meet","imp":1,"text":"Another night in Emberdeep with The Amber Sigil and The Sunlit Almanac in the same place. The two watches nod at each other now. That's as far as it goes.","heroes":["h11","h2","h16","h8","h20","h18","h19"],"parties":["p3","p4"],"loc":"emberdeep","wx":"storm"},{"id":"e3156","day":83,"season":3,"sday":23,"kind":"campfire","imp":2,"text":"Sela lends Quill a dog-eared book. Quill reads it by firelight and argues about the ending for days.","heroes":["h2","h11"],"parties":["p3"],"loc":"emberdeep","wx":"storm"},{"id":"e3189","day":84,"season":3,"sday":24,"kind":"famous_trap","imp":3,"text":"The Dragon's Breath claims Quill in Emberdeep, the first it has caught since the new tenant moved in.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep"},{"id":"e3190","day":84,"season":3,"sday":24,"kind":"delve_day","imp":1,"text":"The Amber Sigil tallies up the second floor of Emberdeep at nightfall: three rooms, taken at full stretch, and the names go in the book (the sealed granary, the tong racks, The Dragon's Breath).","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","pace":"push","stats":{"rooms":3,"empty":2,"size":3,"floor":2,"traps":1,"sprung":1,"trap_inj":2,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e3191","day":84,"season":3,"sday":24,"kind":"delve_done","imp":3,"text":"After 4 days below, The Amber Sigil comes out leaning on whatever is nearest. They took 12 rooms off the map's blank side, got down to the second floor, found the master smith's forge, a ramp of black glass beside the lava-fall, the mint vault and 1 more good room, mapped 38% of it, split 160 silver on the way up and turned back because an injury needed a healer. Emberdeep now stands mostly unexplored (30%), every crew's chalk marks counted.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep","days":4,"bottom":false,"rooms":["the master smith's forge","a ramp of black glass beside the lava-fall"],"gold":160,"out":"Battered","turn":"injured"},{"id":"e3192","day":84,"season":3,"sday":24,"kind":"night","imp":3,"text":"Something sings in the dark outside Emberdeep. Tamsin goes to look and comes back with a trinket and a very quiet manner.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"emberdeep"},{"id":"e3220","day":85,"season":3,"sday":25,"kind":"ambush","imp":3,"text":"Quill hits hardest as the Amber Sigil makes short work of a Bandit Archer and a Bandit on the road to Veldrock. Quill's Backstab finished the fight. Nobody cheered for Quill's From the Rafters, but it won the fight. An arrow that should have found Tamsin found the strap next to the coin pocket instead. \"Check its pockets,\" says Tamsin. Loot: 10 silver each, 1 ration.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f181","foes":["bandit_archer","bandit"],"where":"on the road to Veldrock","won":true,"close":false,"shape":"hero","reworded":-22},{"id":"e3235","day":85,"season":3,"sday":25,"kind":"argument","imp":2,"text":"Sela and Tamsin of The Amber Sigil have a shouting match about whether the last fight was a retreat or a 'tactical repositioning'.","heroes":["h2","h16"],"parties":["p3"]},{"id":"e3236","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Sela practises a magistrate's signature by firelight until it's better than the magistrate's. Forgery, the guild calls it.","heroes":["h2"],"parties":["p3"],"loc":"emberdeep","skill":"forgery"},{"id":"e3302","day":87,"season":3,"sday":27,"kind":"campfire","imp":1,"text":"Sela and Quill invent a scoring system for snoring. Nobody else is consulted.","heroes":["h2","h11"],"parties":["p3"],"loc":"veldrock","wx":"snow"},{"id":"e3325","day":88,"season":3,"sday":28,"kind":"road","imp":3,"text":"Quill finds a small page in the king's livery wandering the road to Ironhaven, quite lost. Quill walks the page to the right road, and the page swears to put in a word.","heroes":["h11","h16","h2"],"parties":["p3"],"road":"ironhaven~veldrock","road_rec":"r714"},{"id":"e3340","day":88,"season":3,"sday":28,"kind":"ability","imp":2,"text":"A hooded figure in an Ironhaven tavern slides Tamsin a pouch of 58 silver and a note of what sells where. 'With the compliments of the house.'","heroes":["h16"],"parties":["p3"],"loc":"ironhaven","skill":"underworld_royalty","sk":"Underworld Royalty","rule":true},{"id":"e3342","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Sela gives a fencing lesson in the Ironhaven square. Eleven children now duel with breadsticks. Blade Dancer: one of the things Sela learned the long way round.","heroes":["h2"],"parties":["p3"],"loc":"ironhaven","skill":"blade_dancer"},{"id":"e3348","day":88,"season":3,"sday":28,"kind":"campfire","imp":1,"text":"Sela reads aloud while Tamsin sharpens blades, and neither wants the chapter to end.","heroes":["h2","h16"],"parties":["p3"],"loc":"ironhaven"},{"id":"e3365","day":89,"season":3,"sday":29,"kind":"wagon","imp":3,"text":"The Amber Sigil buys a covered wagon in Ironhaven for 120 silver. It's called Lady Luck now. Who paid: Tamsin 78, Sela 27, Quill 15.","heroes":["h11","h2","h16"],"parties":["p3"],"loc":"ironhaven","wx":"fog"},{"id":"e3388","day":89,"season":3,"sday":29,"kind":"campfire","imp":1,"text":"Quill and Tamsin invent a scoring system for snoring. Nobody else is consulted.","heroes":["h11","h16"],"parties":["p3"],"loc":"ironhaven","wx":"fog"},{"id":"e3434","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Amber Sigil came up short: earn 3,100 silver between them before the season ends (1,144 of 3,100 silver).","heroes":["h11","h2","h16"],"parties":["p3"]},{"id":"e3449","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Vigil of Carrbridge, to keep the peace: never draw first on another hero (sworn in season 2); The Amber Sigil, never to retreat (sworn in season 2); The Sunlit Almanac, to keep the peace: never draw first on another hero (sworn in season 2); The Scarlet Gallopers, that no one leaves this party (sworn in season 2); Gilded Wall, never to leave a companion behind (sworn in season 2); Verdant Edge, to share every coin (sworn in season 2); Duren, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h3"],"parties":["p2","p3","p4","p5","p6","p8"]}],"roles":{"h11":"Point","h2":"Leader · Blade","h16":"Trail-reader"},"quest":{"what":"Delve","where":"Emberdeep","why":"chasing a rumour: about 60 silver a day each, risk slight; the season goal: to earn 3,100 silver between them before the season ends","floor":0,"floors":3},"tactics":{"front":["h2"],"back":["h11","h16"],"plan":"Sela holds the front; Quill and Tamsin pick off whatever gets close.","traits":{"boldness":0.13,"risk":0.29,"greed":0.46,"sociability":-0.09,"honor":-0.58,"curiosity":-0.17,"temper":-0.11,"loyalty":-0.26},"mix":"3 bows","notes":["One shield. If Sela falls, the line goes with him.","No healer: every wound comes home with them."],"style":["silver-hungry","quick on their feet"],"skills":[{"label":"Damage","skills":[{"hero":"h11","id":"backstab","name":"Backstab","desc":"Strikes the back row from the shadows.","tags":["stealth","crit"],"rank":2,"uses":28},{"hero":"h16","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":1,"uses":9},{"hero":"h2","id":"smite","name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"rank":1,"uses":8},{"hero":"h11","id":"snare","name":"Snare","desc":"A noose of wire, a well-timed tug.","tags":["hunt","stealth"],"rank":1,"uses":7},{"hero":"h2","id":"lunge","name":"Lunge","desc":"Long step, longer reach.","tags":["crit"],"rank":2,"uses":7},{"hero":"h16","id":"fire_arrow","name":"Fire Arrow","desc":"Pitch, a spark, and a hopeful arc.","tags":["fire"],"rank":1,"uses":7},{"hero":"h11","id":"fire_arrow","name":"Fire Arrow","desc":"Pitch, a spark, and a hopeful arc.","tags":["fire"],"rank":1,"uses":6},{"hero":"h11","id":"poisoned_blade","name":"Poisoned Blade","desc":"A smear of something green along the edge.","tags":["stealth"],"rank":3,"uses":6},{"hero":"h2","id":"feint","name":"Feint","desc":"Look over there.","tags":["stealth","crit"],"rank":1,"uses":5},{"hero":"h2","id":"mocking_verse","name":"Mocking Verse","desc":"A rhyme so cutting the goblin's arm goes limp.","tags":["music"],"rank":1,"uses":1},{"hero":"h2","id":"cleave","name":"Cleave","desc":"Hits everything in the front rank.","tags":["rage"],"rank":1,"uses":1},{"hero":"h2","id":"disarm","name":"Disarm","desc":"A twist of the wrist and their sword is on the floor.","tags":["crit"],"rank":1,"uses":0},{"hero":"h16","id":"woods_bite","name":"The Woods Bite","desc":"Every bush on the hill was a trap. They checked.","tags":["nature"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h11","id":"tailwind","name":"Tailwind","desc":"The wind is suddenly on everyone's side.","tags":["storm","travel"],"rank":1,"uses":1}]},{"label":"Tricks","skills":[{"hero":"h11","id":"from_the_rafters","name":"From the Rafters","desc":"Was on the beam the whole time.","tags":["stealth","crit"],"rank":1,"uses":24},{"hero":"h2","id":"perfect_touch","name":"The Perfect Touch","desc":"One clean hit, then another, before the first one has finished stinging.","tags":[],"rank":1,"uses":24},{"hero":"h11","id":"never_where_you_left_them","name":"Never Where You Left Them","desc":"Was just here. Now isn't. Has your purse.","tags":[],"rank":1,"uses":18},{"hero":"h2","id":"second_intention","name":"Second Intention","desc":"Planned the second cut before the first one landed.","tags":["crit"],"rank":2,"uses":14},{"hero":"h16","id":"trip_wire","name":"Trip Wire","desc":"Strung across the path before anyone noticed.","tags":["craft","stealth"],"rank":2,"uses":9},{"hero":"h16","id":"bramble_snare","name":"Bramble Snare","desc":"Brambles, plaited into something that holds.","tags":["nature","craft"],"rank":2,"uses":5},{"hero":"h11","id":"shadow_of_death","name":"Shadow of Death","desc":"Nobody hears them. Nobody needs to.","tags":[],"rank":1,"uses":3},{"hero":"h2","id":"blade_dancer","name":"Blade Dancer","desc":"Fights like it's a waltz and the enemy forgot the steps.","tags":[],"rank":1,"uses":3},{"hero":"h16","id":"bramble_ground","name":"Bramble Ground","desc":"Every bush within a mile has been asked to bite. Most agreed.","tags":[],"rank":1,"uses":1},{"hero":"h11","id":"slip_away","name":"Slip Away","desc":"Was losing. Is now somewhere else.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h11","id":"churchyard_ghost","name":"Churchyard Ghost","desc":"So convincing a ghost that the real ones complain.","tags":["death","stealth"],"rank":1,"uses":0},{"hero":"h16","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","hunt"],"rank":1,"uses":0},{"hero":"h16","id":"snare_field","name":"Snare Field","desc":"Half the enemy finds the snares. The other half finds out.","tags":["nature","craft"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h11","id":"shadowstep","name":"Shadowstep","desc":"Steps into one shadow and out of another.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h11","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h2","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h2","id":"lucky","name":"Lucky","desc":"Things just work out.","tags":["crit"],"rank":1,"uses":0},{"hero":"h2","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"broadheads","name":"Broadheads","desc":"Arrowheads with strong views on armour.","tags":["craft","crit"],"rank":1,"uses":0},{"hero":"h16","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h11","id":"tooth_puller","name":"Tooth Puller","desc":"Village dentist. Steady hand, strong string.","tags":["heal"],"rank":1,"uses":0},{"hero":"h11","id":"trap_seller","name":"Trap Seller","desc":"Every farmer with a fox problem knows their name.","tags":["trade"],"rank":1,"uses":0},{"hero":"h11","id":"barterer","name":"Barterer","desc":"Will swap you anything for anything.","tags":["trade","travel"],"rank":1,"uses":0},{"hero":"h11","id":"vigil","name":"Vigil","desc":"Keeps watch and prays through the small hours.","tags":["holy","guard"],"rank":1,"uses":0},{"hero":"h11","id":"horse_whisperer","name":"Horse Whisperer","desc":"Horses don't go lame on their watch, and thieves can't lead one off.","tags":["ride","beast"],"rank":1,"uses":0},{"hero":"h11","id":"lockpicking","name":"Lockpicking","desc":"Doors are suggestions.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h11","id":"market_gossip","name":"Market Gossip","desc":"Knows what pepper costs in three towns.","tags":["trade"],"rank":1,"uses":0},{"hero":"h2","id":"good_listener","name":"Good Listener","desc":"People tell them things. Then feel better.","tags":["lore"],"rank":2,"uses":0},{"hero":"h2","id":"tinkerer","name":"Tinkerer","desc":"Takes things apart. Usually puts them back.","tags":["craft","arcane"],"rank":1,"uses":0},{"hero":"h2","id":"forgery","name":"Forgery","desc":"Their handwriting is your handwriting.","tags":["stealth","trade"],"rank":1,"uses":0},{"hero":"h2","id":"market_gossip","name":"Market Gossip","desc":"Knows what pepper costs in three towns.","tags":["trade"],"rank":1,"uses":0},{"hero":"h2","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h2","id":"field_forge","name":"Field Forge","desc":"Sets up an anvil on any flat rock and mends what the road broke.","tags":["craft"],"rank":1,"uses":0},{"hero":"h2","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h2","id":"wager_of_honour","name":"Wager of Honour","desc":"Bets the room they can't be touched. Collects.","tags":["crit"],"rank":1,"uses":0},{"hero":"h2","id":"juggler","name":"Juggler","desc":"Keeps five things in the air and the crowd's attention.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"rumourmonger","name":"Rumourmonger","desc":"Hears everything first. Repeats most of it.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h16","id":"linguist","name":"Linguist","desc":"Speaks six languages, including Goblin, badly.","tags":["lore","arcane"],"rank":1,"uses":0},{"hero":"h16","id":"calligrapher","name":"Calligraphy","desc":"Beautiful letters. Even on shopping lists.","tags":["craft","lore"],"rank":1,"uses":0},{"hero":"h16","id":"smith_hands","name":"Smith's Hands","desc":"Fixes and upgrades their own gear.","tags":["craft"],"rank":1,"uses":0},{"hero":"h16","id":"honey_finder","name":"Honey Finder","desc":"Follows the bees. Comes back sticky.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"relic_lore","name":"Relic Lore","desc":"Knows which king owned that spoon.","tags":["trade","lore"],"rank":1,"uses":0},{"hero":"h16","id":"card_sharp","name":"Card Sharp","desc":"The deck is always friendlier in their hands.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"tin_can_line","name":"Tin-Can Line","desc":"Cans on a string round the camp. Nothing sneaks up. Nobody sleeps.","tags":["nature","craft"],"rank":3,"uses":0},{"hero":"h16","id":"angler","name":"Angler","desc":"Has a line in the water before the tent is up.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h11","dmg":2049,"healed":0,"taken":0,"kills":6,"row":"back"},{"hero":"h2","dmg":1753,"healed":0,"taken":0,"kills":7,"row":"front"},{"hero":"h16","dmg":81,"healed":0,"taken":0,"kills":0,"row":"back"}],"ground":{"name":"The Ashveil Crypts","fights":10}},"trophies":[{"boss":"Vessimir the Unburied","monster":"necromancer","place":"The Ashveil Crypts","day":37,"season":2,"fight":"f88"}]};